    private static LessonVisualSeed W(string imageUrl, string alt, string caption,
        string sourceUrl, string license, string author) =>
        new(imageUrl, alt, caption, sourceUrl, "Wikimedia Commons", license, author);

    public static bool TryGet(string courseCode, string lessonTitle, out LessonVisualSeed visual) =>
        Items.TryGetValue($"{courseCode}|{lessonTitle}", out visual!);

    public static IEnumerable<(string CourseCode, string LessonTitle, LessonVisualSeed Visual)> All =>
        Items.Select(item =>
        {
            var parts = item.Key.Split('|', 2);
            return (parts[0], parts[1], item.Value);
        });

    public const int Count = 32;
